100	impl TagIndex {
101	    pub fn build<D: DependencyResolver>(
102	        git: &GitAccess<'_>,
103	        graph: &D,
104	        _cfg: &ResolvedConfig,
105	    ) -> Result<Self, GraphError> {
106	        let mut last = BTreeMap::new();
107	        let mut templates = BTreeMap::new();
108	        let mut pre_cursor = BTreeMap::new();
109	        let diagnostics = Vec::new();
110	
111	        // Fetch the raw tag list exactly once for the whole build, not once
112	        // per package -- see `fetch_all_tags` for why (avoids N gix
113	        // discoveries / N host round-trips for N packages). `git` is shared
114	        // with the caller rather than discovered fresh here, so a single
115	        // `Workspace`-scoped command that also needs git for other reasons
116	        // (e.g. `plan_publish`'s head_sha resolution) doesn't pay for a
117	        // second discovery.
118	        let all_tags = fetch_all_tags(git)?;
119	        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
120	
121	        for pkg in graph.packages() {
122	            let default_tmpl = TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
123	            let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
124	            let sel = select_from_tags(&all_tags, &tmpl, pkg.version_grammar()?)?;
125	            last.insert(pkg.id.clone(), sel.chosen);
126	            templates.insert(pkg.id.clone(), tmpl);
127	            pre_cursor.insert(pkg.id.clone(), None);
128	        }
129	
130	        Ok(TagIndex {
131	            last,
132	            templates,
133	            pre_cursor,
134	            all_tags: all_tags_set,
135	            diagnostics,
136	        })
137	    }
