/// Spec: `TagIndex::build` must compile/scan a given tag-template glob
/// at most once per *distinct* template string, not once per package --
/// a `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template`
/// applies the identical template to every matching package, so N
/// packages sharing one explicit template must cost one glob compile,
/// not N. Reproduces the bug directly: 3 packages all set the identical
/// `tag_template`, and the glob-compile counter must read 1 afterward.
#[test]
fn test_tag_index_build_compiles_shared_glob_template_once() {
    let dir = non_repo_dir();
    let runner = FakeGitTagRunner::new(vec!["release@1.0.0".to_string()]);

    let manifest = ManifestDecl::new("Cargo.toml", ManifestRole::Canonical, ManifestFormat::CargoToml).unwrap();
    let shared_template = TagTemplate::parse("release@{version}").unwrap();

    let pkgs: Vec<Package> = ["pkg-a", "pkg-b", "pkg-c"]
        .iter()
        .map(|name| Package {
            id: PackageId::parse(name).unwrap(),
            manifests: vec![manifest.clone()],
            changelog: None,
            release_trigger: callisto_model::ReleaseTrigger::Changeset,
            publish_to: Vec::new(),
            tag_template: Some(shared_template.clone()),
        })
        .collect();

    let graph = FixedGraph { pkgs };
    let cfg = crate::config::load(dir.path()).unwrap();
    let git = GitAccess::discover(dir.path(), &runner);

    reset_glob_compile_count();
    TagIndex::build(&git, &graph, &cfg).expect("TagIndex::build must succeed");

    assert_eq!(
        glob_compile_count(),
        1,
        "TagIndex::build must compile a shared tag-template glob once for all 3 packages, not once per package"
    );
}

