use std::time::Instant;

use callisto_model::CommitSha;
use callisto_vcs::GitRepository;

#[test]
#[ignore]
fn bench_revwalk() {
    let root = std::path::Path::new("/tmp/revwalk_bench/repo");
    let repo = GitRepository::discover(root).unwrap();
    let since_sha = CommitSha::parse("d98676c5e14b0e638ef785437ef41381861964de").unwrap();

    // warm up
    let commits = repo.commits_since_with_pathspec(Some(&since_sha), &[]).unwrap();
    eprintln!("commits returned: {}", commits.len());

    let start = Instant::now();
    for _ in 0..5 {
        let _ = repo.commits_since_with_pathspec(Some(&since_sha), &[]).unwrap();
    }
    let elapsed = start.elapsed();
    eprintln!("5 runs took {elapsed:?}, avg {:?}", elapsed / 5);
}

